import { useState } from 'react';

export default function UrlScanner() {
  const [url, setUrl] = useState('');
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  async function scanUrl() {
    setLoading(true);
    try {
      const res = await fetch('/api/tools/url-scan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url }),
      });

      const contentType = res.headers.get('content-type');
      if (!contentType || !contentType.includes('application/json')) {
        throw new Error('Server did not return JSON');
      }

      const data = await res.json();
      setResult(data);
    } catch (err) {
      setResult({ verdict: 'Error', signals: [err.message] });
    } finally {
      setLoading(false);
    }
  }

  return (
    <div style={{ padding: '2rem' }}>
      <h2>🔍 URL Scanner</h2>
      <input
        type="text"
        value={url}
        onChange={(e) => setUrl(e.target.value)}
        placeholder="https://example.com"
        style={{ width: '300px', padding: '0.5rem', marginRight: '1rem' }}
      />
      <button onClick={scanUrl} disabled={loading || !url}>
        {loading ? 'Scanning...' : 'Scan'}
      </button>

      {result && (
        <div style={{ marginTop: '2rem' }}>
          <h3>Verdict: {result.verdict}</h3>
          <ul>
            {result.signals?.map((s, i) => (
              <li key={i}>{s}</li>
            ))}
          </ul>
          {result.cert && (
            <div>
              <p><strong>SSL Certificate:</strong></p>
              <p>Issuer: {result.cert.issuer}</p>
              <p>Subject: {result.cert.subject}</p>
              <p>Valid Until: {result.cert.validTo}</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
